import os
import requests

ALCHEMY_NOTIFY_URL = "https://dashboard.alchemy.com/api/delete-webhook"


def delete_address_activity_webhook(webhook_id):
    headers = {
        "X-Alchemy-Token": os.environ["ALCHEMY_AUTH_TOKEN"],
        "Accept": "application/json",
    }
    resp = requests.delete(
        ALCHEMY_NOTIFY_URL,
        params={"webhook_id": webhook_id},
        headers=headers,
        timeout=15,
    )
    result = {"webhook_id": webhook_id, "status_code": resp.status_code}
    if resp.ok:
        result["deleted"] = True
    else:
        result["deleted"] = False
        result["error"] = resp.text[:500]
    return result
